               ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function QuizApp() {
       return `
         <div class="page">
           <header class="hero">
             <p class="eyebrow">Computer languages</p>
             <h1>Quick code quiz</h1>
             <p class="intro">Choose all answers that apply for each question. Each section supports multiple selections.</p>
           </header>

           <section class="quiz-card" aria-labelledby="quiz-title">
             <div class="quiz-content">
               <h2 class="sr-only" id="quiz-title">Computer languages quiz questions</h2>
               <form id="quiz-form">
                 ${quizQuestions.map((question, index) => QuestionField({ question, index })).join("")}

                 <div class="actions">
                   <p class="hint">You can select more than one answer per question.</p>
                   <button type="submit">Submit quiz</button>
                 </div>
               </form>
               <div id="result" class="result" role="status" aria-live="polite" hidden></div>
             </div>
           </section>
         </div>
       `;
     }

     document.getElementById("app").innerHTML = QuizApp();

     document.getElementById("quiz-form").addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedCount = quizQuestions.reduce((total, question) => {
         return total + document.querySelectorAll(`input[name="${question.id}"]:checked`).length;
       }, 0);

       const result = document.getElementById("result");
       result.hidden = false;
       result.textContent = `Quiz submitted with ${selectedCount} selected answer${selectedCount === 1 ? "" : "s"}.`;
     });
   </script>
 </body>
 </html>

')
